#include "dlaa_core/debug_overlay.h"

#include <wrl/client.h>

#include "debug_blit_ps.h"  // generated by fxc: kDebugBlitPs
#include "debug_blit_vs.h"  // generated by fxc: kDebugBlitVs
#include "dlaa_core/log.h"

using Microsoft::WRL::ComPtr;

namespace dlaa_core::debug_overlay {

void Draw(IDXGISwapChain* swap_chain, ID3D11ShaderResourceView* srv, UINT width, UINT height) {
  static ComPtr<ID3D11VertexShader> vs;
  static ComPtr<ID3D11PixelShader> ps;
  static bool failed = false;
  if (failed || !srv) return;
  ComPtr<ID3D11Device> device;
  if (FAILED(swap_chain->GetDevice(IID_PPV_ARGS(&device)))) return;
  if (!vs) {
    if (FAILED(device->CreateVertexShader(kDebugBlitVs, sizeof(kDebugBlitVs), nullptr, &vs)) ||
        FAILED(device->CreatePixelShader(kDebugBlitPs, sizeof(kDebugBlitPs), nullptr, &ps))) {
      Log("DLAA: debug overlay shaders failed");
      failed = true;
      return;
    }
  }
  ComPtr<ID3D11Texture2D> back;
  if (FAILED(swap_chain->GetBuffer(0, IID_PPV_ARGS(&back)))) return;
  D3D11_TEXTURE2D_DESC bd;
  back->GetDesc(&bd);
  if (bd.Width != width || bd.Height != height) return;
  ComPtr<ID3D11RenderTargetView> rtv;
  if (FAILED(device->CreateRenderTargetView(back.Get(), nullptr, &rtv))) return;
  ComPtr<ID3D11DeviceContext> ctx;
  device->GetImmediateContext(&ctx);

  // Save what the draw changes.
  ID3D11RenderTargetView* rtvs[D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT] = {};
  ID3D11DepthStencilView* dsv = nullptr;
  ctx->OMGetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, rtvs, &dsv);
  ID3D11BlendState* blend = nullptr;
  FLOAT blend_factor[4];
  UINT sample_mask = 0;
  ctx->OMGetBlendState(&blend, blend_factor, &sample_mask);
  ID3D11DepthStencilState* ds = nullptr;
  UINT stencil_ref = 0;
  ctx->OMGetDepthStencilState(&ds, &stencil_ref);
  ID3D11RasterizerState* rs = nullptr;
  ctx->RSGetState(&rs);
  D3D11_VIEWPORT viewports[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE];
  UINT viewport_count = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
  ctx->RSGetViewports(&viewport_count, viewports);
  ID3D11InputLayout* layout = nullptr;
  ctx->IAGetInputLayout(&layout);
  D3D11_PRIMITIVE_TOPOLOGY topology;
  ctx->IAGetPrimitiveTopology(&topology);
  ID3D11VertexShader* old_vs = nullptr;
  ID3D11ClassInstance* vs_instances[D3D11_SHADER_MAX_INTERFACES] = {};
  UINT vs_instance_count = D3D11_SHADER_MAX_INTERFACES;
  ctx->VSGetShader(&old_vs, vs_instances, &vs_instance_count);
  ID3D11PixelShader* old_ps = nullptr;
  ID3D11ClassInstance* ps_instances[D3D11_SHADER_MAX_INTERFACES] = {};
  UINT ps_instance_count = D3D11_SHADER_MAX_INTERFACES;
  ctx->PSGetShader(&old_ps, ps_instances, &ps_instance_count);
  ID3D11ShaderResourceView* old_srv = nullptr;
  ctx->PSGetShaderResources(0, 1, &old_srv);

  ctx->OMSetRenderTargets(1, rtv.GetAddressOf(), nullptr);
  ctx->OMSetBlendState(nullptr, nullptr, 0xFFFFFFFF);
  ctx->OMSetDepthStencilState(nullptr, 0);
  ctx->RSSetState(nullptr);
  const D3D11_VIEWPORT viewport = {0.0f, 0.0f, static_cast<float>(bd.Width),
                                   static_cast<float>(bd.Height), 0.0f, 1.0f};
  ctx->RSSetViewports(1, &viewport);
  ctx->IASetInputLayout(nullptr);
  ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
  ctx->VSSetShader(vs.Get(), nullptr, 0);
  ctx->PSSetShader(ps.Get(), nullptr, 0);
  ctx->PSSetShaderResources(0, 1, &srv);
  ctx->Draw(3, 0);

  ctx->PSSetShaderResources(0, 1, &old_srv);
  ctx->PSSetShader(old_ps, ps_instances, ps_instance_count);
  ctx->VSSetShader(old_vs, vs_instances, vs_instance_count);
  ctx->IASetPrimitiveTopology(topology);
  ctx->IASetInputLayout(layout);
  ctx->RSSetViewports(viewport_count, viewports);
  ctx->RSSetState(rs);
  ctx->OMSetDepthStencilState(ds, stencil_ref);
  ctx->OMSetBlendState(blend, blend_factor, sample_mask);
  ctx->OMSetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, rtvs, dsv);
  auto release = [](auto* p) {
    if (p) p->Release();
  };
  for (auto* p : rtvs) release(p);
  release(dsv);
  release(blend);
  release(ds);
  release(rs);
  release(layout);
  release(old_vs);
  for (UINT i = 0; i < vs_instance_count; ++i) release(vs_instances[i]);
  release(old_ps);
  for (UINT i = 0; i < ps_instance_count; ++i) release(ps_instances[i]);
  release(old_srv);
}

}  // namespace dlaa_core::debug_overlay
